# のれん（noren）：いまの絵と同じデザイン・同じ大きさ。温泉の入り口の上にかける、木の竿と、うすい青の布3まい。まん中の布に、温泉のしるし。
# 設計図（じっさいに作れる組み方。単位はマス。大きさは、いまの絵（80×60ドット）に合わせた。入り口の上の高い所にかける）
#   竿：まるい木の竿（半径0.03、x=-0.10〜1.10・高さ1.55）。両はしに、まるい木の玉（半径0.06）。
#   布：うすい青の布3まい（お手本のドットから読みとった形。x=−0.051〜1.059、左0.274・まん中0.50・右0.336。上はとなりとくっつき、左のすきまは高さ0.954から、右のすきまは0.888から下でひらく（下で0.016・0.063））。高さ1.50 → 0.74。上のはしは、輪4つ（x=0.035・0.30・0.62・0.945、はば0.10、高さ1.49〜1.60）で竿に通す。
#   しるし：まん中の布に、温泉のしるし（♨）。お手本の絵から1ドットずつ読みとった形を、布の面のもようにする（クリーム色）。
from blueprint import Part as P
from common import *
import math
ID='noren';GRAD=True;PARALLEL=True;BOTTOM=-32   # 入り口の上の高い所にかけるので、絵は地面より上（いまの絵と同じ所）
VIEWS=[('noren',0)]
CY=0.55;CLOTH=(170,178,200);MARK=(244,236,214);ZT,ZB=1.55,0.74
MARKROWS=['....................................', '....................................', '...................#................', '..................###...............', '............#....###.....##.........', '...........##....###....###.........', '...........##....###....##..........', '..........###...####....##..........', '..........###...####....##..........', '..........###....###....###.........', '..........###....####...###.........', '...........###...####...###.........', '...........####...###....###........', '............###...####...###........', '............###....###...###........', '............###....###...###........', '.......#....###....###...###..##....', '......##....##....###....##....#....', '......##...##.....###....##....#....', '.....###..........##...........##...', '.....###..........#...........###...', '.....####.....................###...', '......####...................####...', '......#####................#####....', '.......#######...........#######....', '........#######################.....', '.........####################.......', '............##############..........', '..............##########............', '....................................']   # 温泉のしるし（♨）：お手本の絵（いまのチップ）から、1ドットずつ読みとった形（行19〜48・列20〜55）
def mark(x,y,z):   # 布の上の場所 → お手本の絵のドット（よこ：64x+0.24+8、たて：−48.8−(z−1)×60.9+91。この3Dの写し方で、お手本と同じ所に重なる）
    col=int(math.floor(64*x+0.24+8))-20;row=int(math.floor(-48.796-(z-1.0)*60.908+91))-19
    if 0<=row<len(MARKROWS) and 0<=col<len(MARKROWS[0]) and MARKROWS[row][col]=='#':return MARK
    return None
def PARTS():
    r=P('竿','frust',((-0.10,CY,ZT),(1.10,CY,ZT),0.03,0.03),WOOD,note='入り口の上の金具にかける（金具は入り口の物）');r.deco=True;L=[r]
    for k,x in enumerate((-0.10,1.10)):L.append(P('竿の玉%d'%(k+1),'ball',(x,CY,ZT,0.06),WOOD,on=('竿',),note='竿のはし'))
    # 布3まい（お手本のドットから読みとった形）：上はとなりとくっつき、左のすきまは高さ0.954から、右のすきまは0.888から下でひらく
    PANELS=[[(-0.051,ZT-0.05),(0.223,ZT-0.05),(0.223,0.954),(0.215,ZB),(-0.051,ZB)],
            [(0.223,ZT-0.05),(0.723,ZT-0.05),(0.723,0.888),(0.699,ZB),(0.231,ZB),(0.223,0.954)],
            [(0.723,ZT-0.05),(1.059,ZT-0.05),(1.059,ZB),(0.762,ZB),(0.723,0.888)]]
    for i,pts in enumerate(PANELS):
        c=notex(P('布%d'%(i+1),'prism',(pts,CY+0.04,CY+0.052,'y'),CLOTH,on=('竿',),note='上のはしを輪で竿に通す'));c.soft1=True
        if i==1:c.decal=mark
        L.append(c)
    for k,xt in enumerate((0.035,0.30,0.62,0.945)):   # 輪：お手本と同じ所に4つ（はば0.10）
        L.append(notex(P('輪%d'%(k+1),'box',(xt-0.05,CY-0.04,ZT-0.06,xt+0.05,CY+0.052,ZT+0.05),CLOTH,bevel=0.01,on=('竿',),note='布の上のはしをおり返して竿に通す輪')))
    return L
